export const code = async (inputs) => {
  // Фолбэк ADR-0017: карточку не отредактировать — шлём новую и переписываем
  // draft новым cardMessageId (копия паттерна reg-consent-pdn/step_15).
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const id = Number(inputs.cardMessageId);
  const prof = (inputs.profile && typeof inputs.profile === 'object') ? inputs.profile : {};
  return {
    draftJson: JSON.stringify({
      eventId: str(inputs.eventId), utm: str(inputs.utm),
      cardMessageId: isFinite(id) && id > 0 ? id : 0, profile: prof,
      step: str(inputs.nextStep)
    })
  };
};

